#!/usr/bin/env bash
# 02_ДЕН: self-contained uploader. No additional module folder required.
# Publishes OpenHelpDesk from feature/engineer-ai + 02_ДЕН to ONLY branch «хуй».
# Requires Git Bash and Python >= 3.9. Does not force-push or modify main.
set -Eeuo pipefail

REPO_URL="https://github.com/Dum-senior/digital-challenge-hackathon.git"
BRANCH='хуй'
BASE='feature/engineer-ai'
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SELF="${BASH_SOURCE[0]}"
SELF_ABSOLUTE="$HERE/$(basename "$SELF")"

fail() { printf '\nОШИБКА: %s\n' "$*" >&2; exit 1; }
command -v git >/dev/null 2>&1 || fail "Git не найден. Установите Git for Windows, затем откройте Git Bash."

PY=()
if command -v python3 >/dev/null 2>&1 && python3 -c 'import sys; assert sys.version_info >= (3, 9)' >/dev/null 2>&1; then
  PY=(python3)
elif command -v python >/dev/null 2>&1 && python -c 'import sys; assert sys.version_info >= (3, 9)' >/dev/null 2>&1; then
  PY=(python)
elif command -v py >/dev/null 2>&1 && py -3 -c 'import sys; assert sys.version_info >= (3, 9)' >/dev/null 2>&1; then
  PY=(py -3)
else
  fail "Нужен Python 3.9 или новее. Установите Python для Windows. pip не нужен."
fi

TMP="$(mktemp -d)" || fail "Невозможно создать временную папку."
[[ -n "$TMP" && "$TMP" != / ]] || fail "Неверная временная папка."
cleanup() { if [[ -n "${TMP:-}" && "$TMP" != / && -d "$TMP" ]]; then rm -rf -- "$TMP"; fi; }
trap cleanup EXIT

printf '\n02_ДЕН: распаковываю ВСТРОЕННЫЙ код (папка с модулем НЕ нужна)...\n'
"${PY[@]}" - "$SELF" "$TMP/payload" <<'PYTHON_EXTRACT'
import sys, pathlib, zipfile, io, base64, hashlib
src=pathlib.Path(sys.argv[1]).read_bytes()
marker=b'\n__DEN_PAYLOAD_ZIP_BASE64__\n'
if src.count(marker)!=1:
    raise SystemExit('ОШИБКА: повреждён встроенный архив модуля. Скачайте скрипт заново.')
try:
    data=base64.b64decode(src.split(marker,1)[1].strip(),validate=True)
    if hashlib.sha256(data).hexdigest() != '2b7dee79607cb27c5bf4be8903943b86f112db8c2645290ba3570a625c987599':
        raise ValueError('SHA-256 checksum mismatch')
    dest=pathlib.Path(sys.argv[2]); dest.mkdir(parents=True,exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        for member in z.infolist():
            path=pathlib.PurePosixPath(member.filename)
            if member.is_dir(): continue
            if path.is_absolute() or '..' in path.parts:
                raise ValueError('unsafe filename in payload')
        z.extractall(dest)
except Exception as error:
    raise SystemExit('ОШИБКА: встроенный архив не прошёл проверку: '+str(error))
print('Код успешно распакован и проверен.')
PYTHON_EXTRACT
PAYLOAD="$TMP/payload/DEN_REVISION_2026_11_14"
[[ -f "$PAYLOAD/apply_to_openhelpdesk.py" && -f "$PAYLOAD/overlay/src/IntakeDispatcher.php" ]] \
  || fail "Встроенный пакет неполный. Скачайте скрипт заново."

printf '\nПубликация в: %s\nВетка: %s\nОснова: %s\n' "$REPO_URL" "$BRANCH" "$BASE"
printf 'Если ветка ещё не очищена, сначала выполните 01_clear_branch.sh.\n'
printf '1/6: Клонирую ветку...\n'
git clone --quiet --single-branch --branch "$BRANCH" "$REPO_URL" "$TMP/work" \
  || fail "Не получилось клонировать ветку. Проверьте доступ к GitHub."
cd "$TMP/work"
[[ "$(git branch --show-current)" == "$BRANCH" ]] || fail "Ошибка проверки целевой ветки."
[[ -z "$(git status --porcelain)" ]] || fail "Найдены неожиданные локальные изменения."
if [[ -n "$(git ls-tree -r --name-only HEAD)" ]]; then
  fail "Ветка '$BRANCH' не пуста. Сначала выполните 01_clear_branch.sh. Ничего не удалено."
fi

printf '2/6: Загружаю исходники OpenHelpDesk...\n'
git fetch --quiet origin "refs/heads/$BASE:refs/remotes/origin/$BASE" \
  || fail "Не удалось получить основу $BASE."
git cat-file -e "refs/remotes/origin/$BASE:src/EngineerAssistant.php" \
  || fail "В $BASE не найден EngineerAssistant.php; неправильная основа."

printf '3/6: Создаю интеграционный коммит без изменения исходной ветки...\n'
git merge --no-commit --no-ff -s ours "refs/remotes/origin/$BASE" \
  || fail "Ошибка подготовки объединения историй."
git read-tree --reset -u "refs/remotes/origin/$BASE" \
  || fail "Ошибка получения исходного дерева OpenHelpDesk."

printf '4/6: Устанавливаю модуль ИИ-диспетчера...\n'
"${PY[@]}" "$PAYLOAD/apply_to_openhelpdesk.py" "$PWD" \
  || fail "Ошибка установки модуля. Push не выполнен."
mkdir -p scripts/den docs/team
cp "$TMP/payload/01_clear_branch.sh" scripts/den/01_clear_branch.sh
cp "$SELF_ABSOLUTE" scripts/den/02_push_dispatcher.sh
cp "$PAYLOAD/README.md" docs/team/dispatcher-installation.md
cp "$PAYLOAD/TEST_RESULTS_02_DEN.md" docs/team/dispatcher-test-results.md

printf '5/6: Создаю коммит...\n'
git add -A
if git diff --cached --quiet; then
  fail "Нет изменений для коммита."
fi
if [[ -z "$(git config user.name || true)" ]]; then
  git config user.name 'Dispatcher Git Script'
fi
if [[ -z "$(git config user.email || true)" ]]; then
  git config user.email 'dispatcher-script@users.noreply.github.com'
fi
git commit --quiet -m 'feat(dispatcher): OpenHelpDesk base + full AI intake module'
printf 'Количество файлов: %s\n' "$(git ls-files | wc -l | tr -d ' ')"

printf '6/6: Публикую в ветку %s (без --force)...\n' "$BRANCH"
git push origin "HEAD:refs/heads/$BRANCH" \
  || fail "GitHub не разрешил push. Проверьте доступ или наличие новых коммитов."
printf '\nГОТОВО! Код опубликован в ветке %s. main не изменён.\n' "$BRANCH"
printf 'https://github.com/Dum-senior/digital-challenge-hackathon/tree/%%D1%%85%%D1%%83%%D0%%B9\n'
exit 0
__DEN_PAYLOAD_ZIP_BASE64__

